// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate, Easing } from '../remotionShim';
import { getLength, getPointAtLength, getTangentAtLength, evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();

// Define the pipe path going from Bottom (2100) to Top (-100)
// This ensures evolvePath draws it from bottom to top, creating a "filling up" effect.
const PIPE_PATH = `
  M 250 2100
  L 250 1600
  C 250 1400, 830 1400, 830 1200
  L 830 800
  C 830 600, 250 600, 250 400
  L 250 -100
`;

// Calculate path length once at module level for performance
const PATH_LENGTH = getLength(PIPE_PATH);



export type RevenuePipelineProps = Record<string, any>;

const RevenuePipeline: React.FC<RevenuePipelineProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 10,
  pipeOuterColor = "#475569",
  pipeInnerColor = "#1e293b",
  moneyBackgroundColor = "#14532d",
  moneyPrimaryColor = "#4ade80",
  moneySecondaryColor = "#22c55e",
  particleCount = 150,
  title = "REVENUE PIPELINE",
  titleFontFamily = "SpaceGrotesk",
  titleColor = "#ffffff",
  moneyFontFamily = "RobotoMono",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const fontFamilies = {
    Inter: interFamily,
    SpaceGrotesk: spaceGroteskFamily,
    RobotoMono: robotoMonoFamily,
  };

  const titleFont = fontFamilies[titleFontFamily];
  const moneyFont = fontFamilies[moneyFontFamily];

  // The liquid fills up smoothly across the animation duration
  const fillProgress = interpolate(
    frame,
    [fps * 0.5, fps * (durationInSeconds - 1)],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    }
  );

  // Evolve the path from bottom to top to act as a reveal mask
  const evolution = evolvePath(fillProgress, PIPE_PATH);

  // Deterministically generate particle properties outside the render cycle
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const seed = i;
      const size = 20 + random(seed + "size") * 30; // 20px to 50px
      const speed = 3 + random(seed + "speed") * 5; // 3 to 8 px per frame
      const startOffset = random(seed + "start") * PATH_LENGTH;
      const isPrimary = random(seed + "color") > 0.5;
      const rotationOffset = random(seed + "rot") * 360;
      const rotationSpeed = (random(seed + "rotSpd") - 0.5) * 8;
      // Spread particles across the width of the inner pipe (120px wide)
      const lateralOffset = (random(seed + "lat") - 0.5) * 70;
      return {
        id: i,
        size,
        speed,
        startOffset,
        isPrimary,
        rotationOffset,
        rotationSpeed,
        lateralOffset,
      };
    });
  }, [particleCount]);

  // Calculate the position and tangent of the "surface" of the liquid for the cap effect
  const surfaceDistance = fillProgress * PATH_LENGTH;
  let surfacePoint = { x: 250, y: 2100 };
  let surfaceTangent = { x: 0, y: -1 };
  
  try {
    surfacePoint = getPointAtLength(PIPE_PATH, surfaceDistance);
    surfaceTangent = getTangentAtLength(PIPE_PATH, surfaceDistance);
  } catch (e) {
    // Fallback if path math fails at extreme 0 length
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Overlay Text */}
      <div
        style={{
          position: "absolute",
          top: height * 0.15,
          right: width * 0.08,
          width: width * 0.6,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end",
          textAlign: "right",
          fontFamily: titleFont,
          color: titleColor,
          zIndex: 10,
        }}
      >
        <h1
          style={{
            fontSize: 72,
            fontWeight: 800,
            margin: 0,
            lineHeight: 1.1,
            textShadow: "0px 8px 24px rgba(0,0,0,0.6)",
            letterSpacing: "-0.02em",
          }}
        >
          {title}
        </h1>
        <div
          style={{
            width: 120,
            height: 10,
            backgroundColor: moneyPrimaryColor,
            marginTop: 24,
            borderRadius: 5,
            boxShadow: `0 0 20px ${moneyPrimaryColor}80`,
          }}
        />
      </div>

      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        <defs>
          {/* 
            This mask uses the evolvePath strokeDasharray to reveal 
            its contents from the bottom of the pipe up to the top.
          */}
          <mask id="fill-mask">
            <path
              d={PIPE_PATH}
              stroke="white"
              strokeWidth={120} // Matches the inner diameter of the pipe
              fill="none"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={evolution.strokeDasharray}
              strokeDashoffset={evolution.strokeDashoffset}
            />
          </mask>

          <filter id="glow">
            <feGaussianBlur stdDeviation="15" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* 1. Outer Pipe Shell (Lead/Metal) */}
        <path
          d={PIPE_PATH}
          stroke={pipeOuterColor}
          strokeWidth={160}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* 2. Inner Pipe Core (Dark/Hollow background) */}
        <path
          d={PIPE_PATH}
          stroke={pipeInnerColor}
          strokeWidth={120}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* 3. The Money Fill Group (Masked by the rising liquid level) */}
        <g mask="url(#fill-mask)">
          {/* Liquid Base Color */}
          <path
            d={PIPE_PATH}
            stroke={moneyBackgroundColor}
            strokeWidth={120}
            fill="none"
            strokeLinecap="round"
            strokeLinejoin="round"
          />

          {/* Dollar Sign Particles flowing downwards */}
          {particles.map((p) => {
            // Subtracting speed moves them from Top (MAX length) down to Bottom (0)
            let currentDistance = (p.startOffset - frame * p.speed) % PATH_LENGTH;
            if (currentDistance < 0) currentDistance += PATH_LENGTH;

            let point = { x: 0, y: 0 };
            let normal = { x: 1, y: 0 };
            
            try {
              point = getPointAtLength(PIPE_PATH, currentDistance);
              const tangent = getTangentAtLength(PIPE_PATH, currentDistance);
              normal = { x: -tangent.y, y: tangent.x };
            } catch (e) {
              return null;
            }

            const x = point.x + normal.x * p.lateralOffset;
            const y = point.y + normal.y * p.lateralOffset;
            const rotation = p.rotationOffset + frame * p.rotationSpeed;
            const color = p.isPrimary ? moneyPrimaryColor : moneySecondaryColor;

            return (
              <text
                key={p.id}
                x={x}
                y={y}
                fontSize={p.size}
                fill={color}
                fontFamily={moneyFont}
                fontWeight="900"
                textAnchor="middle"
                dominantBaseline="middle"
                transform={`rotate(${rotation}, ${x}, ${y})`}
                style={{ transition: "none" }}
              >
                $
              </text>
            );
          })}
        </g>

        {/* 4. Surface level cap (Creates a 3D cross-section at the top of the liquid) */}
        {fillProgress > 0.01 && fillProgress < 0.99 && (
          <ellipse
            cx={surfacePoint.x}
            cy={surfacePoint.y}
            rx={60}
            ry={15}
            fill={moneyPrimaryColor}
            transform={`rotate(${(Math.atan2(surfaceTangent.y, surfaceTangent.x) * 180) / Math.PI + 90}, ${surfacePoint.x}, ${surfacePoint.y})`}
            filter="url(#glow)"
            opacity={interpolate(
              fillProgress,
              [0.01, 0.05, 0.95, 0.99],
              [0, 1, 1, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            )}
          />
        )}

        {/* 5. Glass / Metal Reflections to give the pipe a cylindrical 3D feel */}
        <path
          d={PIPE_PATH}
          stroke="#ffffff"
          strokeWidth={12}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity={0.12}
          transform="translate(-30, -30)" // Shifts highlight to the top-left edge
        />
        <path
          d={PIPE_PATH}
          stroke="#ffffff"
          strokeWidth={4}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity={0.25}
          transform="translate(-20, -20)"
        />
      </svg>
    </AbsoluteFill>
  );
};

export default RevenuePipeline;